package com.ruoyi.system.service.impl;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.common.utils.StringUtils;
import com.ruoyi.common.utils.uuid.IdUtils;
import com.ruoyi.system.domain.shop.MallMemberAddress;
import com.ruoyi.system.domain.shop.MallMemberCoupon;
import com.ruoyi.system.domain.shop.MallOrder;
import com.ruoyi.system.domain.shop.MallOrderCreateRequest;
import com.ruoyi.system.domain.shop.MallOrderItem;
import com.ruoyi.system.domain.shop.MallProductSku;
import com.ruoyi.system.mapper.shop.MallOrderMapper;
import com.ruoyi.system.service.IMallOrderService;
import com.ruoyi.system.service.ISysConfigService;

@Service public class MallOrderServiceImpl implements IMallOrderService {
 @Autowired private MallOrderMapper orderMapper;
 @Autowired private ISysConfigService configService;
 public List<MallOrder> selectOrderList(MallOrder order){List<MallOrder> list=orderMapper.selectOrderList(order);for(MallOrder item:list){item.setReceiverPhone(mask(item.getReceiverPhone()));item.setDetailAddress("***");}return list;} public MallOrder selectOrderById(Long id){MallOrder order=selectOrderSensitiveById(id);if(order!=null){order.setReceiverPhone(mask(order.getReceiverPhone()));order.setDetailAddress("***");}return order;} public MallOrder selectOrderSensitiveById(Long id){MallOrder order=orderMapper.selectOrderById(id);if(order!=null)order.setItems(orderMapper.selectOrderItems(id));return order;} private String mask(String phone){return phone==null?null:phone.replaceAll("(\\d{3})\\d{4}(\\d{4})","$1****$2");}

 @Transactional(rollbackFor=Exception.class) public MallOrder createOrder(MallOrderCreateRequest request){validateCreateRequest(request);MallOrder existing=orderMapper.selectOrderByMemberRequest(request.getMemberId(),request.getClientRequestNo());if(existing!=null)return selectOrderSensitiveById(existing.getOrderId());if(orderMapper.selectActiveMember(request.getMemberId())==null)throw new ServiceException("会员不存在或已禁用");MallMemberAddress address=orderMapper.selectMemberAddress(request.getMemberId(),request.getAddressId());if(address==null)throw new ServiceException("收货地址不存在");validateDeliveryRegion(address);Map<Long,Integer> quantities=new TreeMap<Long,Integer>();for(MallOrderCreateRequest.Item item:request.getItems())quantities.put(item.getSkuId(),quantities.getOrDefault(item.getSkuId(),0)+item.getQuantity());String orderNo=IdUtils.fastSimpleUUID();List<MallOrderItem> items=new ArrayList<MallOrderItem>();long productAmount=0L;for(Map.Entry<Long,Integer> entry:quantities.entrySet()){MallOrderItem item=orderMapper.selectSkuForOrder(entry.getKey());if(item==null)throw new ServiceException("商品SKU不可售");MallProductSku stock=orderMapper.selectSkuStockForUpdate(entry.getKey());if(stock==null||stock.getAvailableStock()<entry.getValue())throw new ServiceException("商品库存不足");item.setQuantity(entry.getValue());item.setLineAmount(item.getSalePriceSnapshot()*entry.getValue());item.setDiscountAmount(0L);item.setPayableAmount(item.getLineAmount());productAmount+=item.getLineAmount();if(orderMapper.lockSkuStock(entry.getKey(),entry.getValue())==0)throw new ServiceException("商品库存不足");orderMapper.insertInventoryBizLog(entry.getKey(),"LOCK",orderNo,stock.getAvailableStock(),stock.getAvailableStock()-entry.getValue(),stock.getLockedStock(),stock.getLockedStock()+entry.getValue(),"MEMBER",String.valueOf(request.getMemberId()),"创建订单锁定库存");items.add(item);}long freightAmount=calculateFreightAmount(productAmount);MallMemberCoupon coupon=null;long discountAmount=0L;if(request.getMemberCouponId()!=null){coupon=orderMapper.selectMemberCouponForUpdate(request.getMemberCouponId(),request.getMemberId());if(coupon==null||coupon.getThresholdAmountSnapshot()>productAmount)throw new ServiceException("优惠券不可用于当前订单");discountAmount=Math.min(coupon.getDiscountAmountSnapshot(),productAmount);if(discountAmount>0)allocateDiscount(items,productAmount,discountAmount);}MallOrder order=new MallOrder();order.setOrderNo(orderNo);order.setMemberId(request.getMemberId());order.setClientRequestNo(request.getClientRequestNo());order.setOrderStatus("PENDING_PAYMENT");order.setProductAmount(productAmount);order.setFreightAmount(freightAmount);order.setDiscountAmount(discountAmount);order.setPayableAmount(productAmount+freightAmount-discountAmount);copyAddress(order,address);order.setBuyerRemark(request.getBuyerRemark());if(coupon!=null){order.setCouponNameSnapshot(coupon.getCouponNameSnapshot());order.setCouponThresholdSnapshot(coupon.getThresholdAmountSnapshot());order.setCouponDiscountSnapshot(coupon.getDiscountAmountSnapshot());}orderMapper.insertOrder(order);if(coupon!=null&&orderMapper.lockCoupon(coupon.getMemberCouponId(),request.getMemberId(),order.getOrderId(),productAmount)==0)throw new ServiceException("优惠券锁定失败");for(MallOrderItem item:items){item.setOrderId(order.getOrderId());orderMapper.insertOrderItem(item);}orderMapper.insertOrderLog(order.getOrderId(),"CREATE",null,"PENDING_PAYMENT","MEMBER",String.valueOf(request.getMemberId()),"会员创建订单");if(order.getPayableAmount()==0L)paySuccess(order.getOrderId(),"FREE",orderNo,0L,"SYSTEM");return selectOrderSensitiveById(order.getOrderId());}

 @Transactional(rollbackFor=Exception.class) public int paySuccess(Long id,String payChannel,String channelTradeNo,Long paidAmount,String operator){if(id==null||StringUtils.isBlank(payChannel)||StringUtils.isBlank(channelTradeNo)||paidAmount==null||paidAmount<0)throw new ServiceException("支付参数不完整");MallOrder order=selectOrderSensitiveById(id);if(order==null)throw new ServiceException("订单不存在");if("PENDING_SHIPMENT".equals(order.getOrderStatus())&&payChannel.equals(order.getPayChannel())&&channelTradeNo.equals(order.getChannelTradeNo())&&paidAmount.equals(order.getPaidAmount()))return 1;if(!"PENDING_PAYMENT".equals(order.getOrderStatus()))throw new ServiceException("订单状态不允许支付确认");if(!paidAmount.equals(order.getPayableAmount()))throw new ServiceException("支付金额与订单应付金额不一致");if(orderMapper.payPendingOrder(id,payChannel,channelTradeNo,paidAmount)==0)throw new ServiceException("订单支付确认失败");for(MallOrderItem item:order.getItems()){MallProductSku sku=orderMapper.selectSkuStockForUpdate(item.getSkuId());if(sku==null||sku.getLockedStock()<item.getQuantity())throw new ServiceException("订单库存状态异常");if(orderMapper.deductLockedStock(item.getSkuId(),item.getQuantity())==0)throw new ServiceException("库存实扣失败");orderMapper.insertInventoryBizLog(item.getSkuId(),"DEDUCT",order.getOrderNo(),sku.getAvailableStock(),sku.getAvailableStock(),sku.getLockedStock(),sku.getLockedStock()-item.getQuantity(),"SYSTEM",operator,"支付成功实扣库存");}if(orderMapper.useCoupon(id)>0)orderMapper.increaseCouponUsed(id);orderMapper.insertOrderLog(id,"PAY","PENDING_PAYMENT","PENDING_SHIPMENT","SYSTEM",operator,"支付成功确认");return 1;}

 @Transactional(rollbackFor=Exception.class) public int cancelOrder(Long id,String reason,String operator){MallOrder order=selectOrderSensitiveById(id);if(order==null)throw new ServiceException("订单不存在");if(orderMapper.cancelPendingOrder(id,reason,operator)==0)throw new ServiceException("仅待支付订单可以取消");for(MallOrderItem item:order.getItems()){MallProductSku sku=orderMapper.selectSkuStockForUpdate(item.getSkuId());if(sku==null||sku.getLockedStock()<item.getQuantity())throw new ServiceException("订单库存状态异常");if(orderMapper.releaseSkuStock(item.getSkuId(),item.getQuantity())==0)throw new ServiceException("库存释放失败");orderMapper.insertInventoryLog(item.getSkuId(),order.getOrderNo(),sku.getAvailableStock(),sku.getAvailableStock()+item.getQuantity(),sku.getLockedStock(),sku.getLockedStock()-item.getQuantity(),operator);}orderMapper.unlockCoupon(id);orderMapper.insertOrderLog(id,"CANCEL","PENDING_PAYMENT","CANCELED","ADMIN",operator,"后台取消待支付订单");return 1;}
 @Transactional(rollbackFor=Exception.class) public int closeExpiredOrders(){int count=0;for(MallOrder order:orderMapper.selectExpiredPendingOrders()){try{cancelOrder(order.getOrderId(),"订单支付超时关闭","SYSTEM");count++;}catch(ServiceException ignored){}}return count;}
 @Transactional(rollbackFor=Exception.class) public int shipOrder(Long id,String company,String logisticsNo,String operator){if(company==null||company.trim().isEmpty()||logisticsNo==null||logisticsNo.trim().isEmpty())throw new ServiceException("物流公司和运单号不能为空");if(orderMapper.shipPendingOrder(id,company,logisticsNo,operator)==0)throw new ServiceException("仅待发货订单可以发货");orderMapper.insertOrderLog(id,"SHIP","PENDING_SHIPMENT","SHIPPED","ADMIN",operator,"后台订单发货");return 1;}
 @Transactional(rollbackFor=Exception.class) public int completeOrder(Long id,String operator){if(orderMapper.completeShippedOrder(id,operator)==0)throw new ServiceException("仅已发货订单可以确认完成");orderMapper.insertOrderLog(id,"COMPLETE","SHIPPED","COMPLETED","ADMIN",operator,"后台确认订单完成");return 1;}
 private void validateCreateRequest(MallOrderCreateRequest request){if(request==null||request.getMemberId()==null||StringUtils.isBlank(request.getClientRequestNo())||request.getAddressId()==null||request.getItems()==null||request.getItems().isEmpty())throw new ServiceException("创建订单参数不完整");for(MallOrderCreateRequest.Item item:request.getItems())if(item==null||item.getSkuId()==null||item.getQuantity()==null||item.getQuantity()<1)throw new ServiceException("订单商品数量非法");}
 public Long calculateFreightAmount(Long productAmount){long amount=amountConfig("mall.freight.amount");long threshold=amountConfig("mall.freight.freeThreshold");return threshold>0&&productAmount>=threshold?0L:amount;}
 private long amountConfig(String key){String value=configService.selectConfigByKey(key);if(StringUtils.isBlank(value))return 0L;try{long amount=Long.parseLong(value);if(amount<0)throw new NumberFormatException();return amount;}catch(NumberFormatException e){throw new ServiceException("商城金额配置非法");}}
 private void validateDeliveryRegion(MallMemberAddress address){String unsupported=configService.selectConfigByKey("mall.delivery.unsupportedRegionCodes");if(StringUtils.isBlank(unsupported))return;for(String code:unsupported.split(",")){String value=code.trim();if(value.equals(address.getProvinceCode())||value.equals(address.getCityCode())||value.equals(address.getDistrictCode()))throw new ServiceException("该收货地址暂不支持配送");}}
 private void allocateDiscount(List<MallOrderItem> items,long productAmount,long discountAmount){long allocated=0L;for(int i=0;i<items.size();i++){MallOrderItem item=items.get(i);long discount=i==items.size()-1?discountAmount-allocated:BigDecimal.valueOf(item.getLineAmount()).multiply(BigDecimal.valueOf(discountAmount)).divide(BigDecimal.valueOf(productAmount),0,RoundingMode.DOWN).longValue();item.setDiscountAmount(discount);item.setPayableAmount(item.getLineAmount()-discount);allocated+=discount;}}
 private void copyAddress(MallOrder order,MallMemberAddress address){order.setReceiverName(address.getReceiverName());order.setReceiverPhone(address.getReceiverPhone());order.setProvinceCode(address.getProvinceCode());order.setProvinceName(address.getProvinceName());order.setCityCode(address.getCityCode());order.setCityName(address.getCityName());order.setDistrictCode(address.getDistrictCode());order.setDistrictName(address.getDistrictName());order.setDetailAddress(address.getDetailAddress());}
}
